"""Operaciones aritméticas básicas.

Todas las funciones son puras: no mutan sus argumentos ni escriben estado.
El registro de lo ejecutado es responsabilidad de `calculadora.historial`.
"""

from __future__ import annotations

Numero = int | float


def sumar(a: Numero, b: Numero) -> Numero:
    """Devuelve `a + b`."""
    return a + b


def restar(a: Numero, b: Numero) -> Numero:
    """Devuelve `a - b`."""
    return a - b


def multiplicar(a: Numero, b: Numero) -> Numero:
    """Devuelve `a * b`."""
    return a * b


def dividir(a: Numero, b: Numero) -> float:
    """Devuelve `a / b`.

    Lanza `ValueError` con un mensaje propio en vez de dejar escapar el
    de CPython: quien llama necesita saber qué operación falló, no solo que
    hubo una división por cero en algún sitio.
    """
    if b == 0:
        raise ValueError("No se puede dividir entre cero")
    return a / b


def potencia(base: Numero, exponente: Numero) -> Numero:
    """Devuelve `base ** exponente`."""
    return base**exponente


def cuadrado(numero: Numero) -> Numero:
    """Devuelve `numero ** 2`."""
    return numero**2


def raiz(radicando: Numero, indice: int = 2) -> float:
    """Raíz n-ésima de `radicando`.

    Se rechaza el radicando negativo con índice par porque el resultado no es
    real y devolver un complejo sorprendería a quien usa una calculadora.
    """
    if indice == 0:
        raise ValueError("El índice de la raíz no puede ser cero.")
    if radicando < 0 and indice % 2 == 0:
        raise ValueError("No existe raíz real de índice par para un negativo.")
    if radicando < 0:
        return -((-radicando) ** (1 / indice))
    return radicando ** (1 / indice)


def porcentaje(total: Numero, parte: Numero) -> float:
    """Qué porcentaje representa `parte` sobre `total`."""
    if total == 0:
        raise ZeroDivisionError("El total no puede ser cero.")
    return (parte / total) * 100

"""Pruebas de las operaciones aritméticas."""

import pytest

from calculadora import operaciones


def test_sumar():
    assert operaciones.sumar(2, 3) == 5
    assert operaciones.sumar(-1, 1) == 0


def test_restar():
    assert operaciones.restar(10, 4) == 6


def test_multiplicar():
    assert operaciones.multiplicar(3, 4) == 12
    assert operaciones.multiplicar(5, 0) == 0


def test_dividir():
    assert operaciones.dividir(10, 4) == 2.5


def test_dividir_entre_cero_lanza():
    with pytest.raises(ValueError, match="No se puede dividir entre cero"):
        operaciones.dividir(1, 0)


def test_potencia():
    assert operaciones.potencia(2, 10) == 1024


def test_cuadrado():
    assert operaciones.cuadrado(4) == 16
    assert operaciones.cuadrado(-3) == 9
    assert operaciones.cuadrado(0) == 0


def test_raiz_cuadrada():
    assert operaciones.raiz(9) == 3


def test_raiz_cubica_de_negativo():
    assert operaciones.raiz(-27, 3) == pytest.approx(-3)


def test_raiz_par_de_negativo_lanza():
    with pytest.raises(ValueError):
        operaciones.raiz(-4, 2)


def test_porcentaje():
    assert operaciones.porcentaje(200, 50) == 25

